//	RETURNING id, tenant_id, entity_id, person_type, first_name, last_name, middle_name, email, phone, birth_date, national_id, tax_id, address, metadata, is_active, created_at, updated_at, deleted_at
func (q *Queries) UpdatePerson(ctx context.Context, arg UpdatePersonParams) (*Person, error) {
	row := q.db.QueryRow(ctx, updatePerson,
		arg.ID,
		arg.EntityID,
		arg.PersonType,
		arg.FirstName,
		arg.LastName,
		arg.MiddleName,
		arg.Email,
		arg.Phone,
		arg.BirthDate,
		arg.NationalID,
		arg.TaxID,
		arg.Address,
		arg.Metadata,
		arg.IsActive,
	)
	var i Person
	err := row.Scan(
		&i.ID,
		&i.TenantID,
		&i.EntityID,
		&i.PersonType,
		&i.FirstName,
		&i.LastName,
		&i.MiddleName,
		&i.Email,
		&i.Phone,
		&i.BirthDate,
		&i.NationalID,
		&i.TaxID,
		&i.Address,
		&i.Metadata,
		&i.IsActive,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.DeletedAt,
	)
	return &i, err
}
